/* The root holds the trigger's place in the page. The surface floats above it and grows into the panel, so opening never pushes content. */
.root {
  position: relative;
  display: inline-block;
  height: var(--control-height-md);
  vertical-align: top;
  color: var(--foreground);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-body);
  line-height: var(--leading-body);
}
.root { z-index: 0; transition: z-index 0s linear .5s; }
.root[data-open] { z-index: 30; transition-delay: 0s; }
.root:not([data-open]) .surface { z-index: 0; }
.root *, .root *::before, .root *::after { box-sizing: border-box; }

/* One material from trigger to panel. Size, corners, and offset come from springs; the border is an overlay so it never changes a measurement. */
.surface {
  position: absolute;
  z-index: 2;
  top: 0;
  left: 0;
  overflow: clip;
  background: var(--surface-raised);
  box-shadow: var(--shadow-resting);
  transition: box-shadow var(--duration-considered) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard);
}
.surface::after { content: ""; position: absolute; inset: 0; border: 1px solid var(--border); border-radius: inherit; pointer-events: none; transition: border-color var(--duration-fast) var(--ease-standard); }
.root[data-open] .surface { box-shadow: var(--shadow-floating); }

/* Trigger */
/* The trigger sits in flow above the surface while closed; when open, the surface and its panel rise over it. */
.trigger {
  position: relative;
  z-index: 1;
  display: inline-flex;
  width: max-content;
  height: var(--control-height-md);
  align-items: center;
  gap: 10px;
  padding: 0 12px 0 14px;
  border: 0;
  background: transparent;
  color: var(--foreground);
  cursor: pointer;
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  -webkit-tap-highlight-color: transparent;
}
.trigger:disabled { cursor: default; }
.trigger[inert] { pointer-events: none; }
.triggerIcon, .chevron { display: grid; flex: none; place-items: center; color: var(--text-secondary); }
.chevron { color: var(--text-muted); }
.value { display: inline-flex; font-variant-numeric: tabular-nums; }
.value[data-empty] { color: var(--text-secondary); font-weight: 400; }

/* Words roll in their own slots; a leaving word pops out of flow so the next one never waits for space. */
.rolling { display: inline-flex; gap: .28em; white-space: nowrap; }
.word { position: relative; display: inline-block; }
.wordInner { display: inline-block; }

/* Panel */
.panel { position: absolute; top: 0; left: 0; width: max-content; padding: 10px; --cell: 36px; }
.body { display: flex; gap: 10px; }

.rail { position: relative; display: flex; width: 9.25rem; flex: none; flex-direction: column; gap: 2px; padding-right: 10px; border-right: 1px solid var(--border-subtle); }
.railHighlight { position: absolute; top: 0; left: 0; border-radius: 12px; background: color-mix(in oklch, var(--foreground) 6.5%, transparent); pointer-events: none; }
.preset {
  position: relative;
  display: flex;
  height: 32px;
  flex: none;
  align-items: center;
  padding: 0 12px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  text-align: left;
  white-space: nowrap;
  -webkit-tap-highlight-color: transparent;
  transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard);
}
.preset[aria-pressed="true"] { color: var(--foreground); font-weight: 500; }

.calendars { position: relative; padding: 0 2px; }
.navButton {
  position: absolute;
  z-index: 2;
  top: 0;
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard);
}
.navButton[data-side="prev"] { left: 2px; }
.navButton[data-side="next"] { right: 2px; }
.navButton:active:not(:disabled) { transform: scale(.92); }
.navButton:disabled { opacity: .35; cursor: default; }

/* Months slide horizontally inside a clipped window that keeps a little room for the blur. */
.viewport { position: relative; overflow: clip; overflow-clip-margin: 2px; }
.months { display: flex; gap: 24px; }
.month { width: calc(var(--cell) * 7); }
.monthTitle { height: 32px; margin: 0; color: var(--foreground); font-weight: 500; line-height: 32px; text-align: center; white-space: nowrap; }
.grid { display: grid; }
.weekdays { display: grid; height: 28px; align-items: center; color: var(--text-muted); font-size: var(--text-xs); grid-template-columns: repeat(7, var(--cell)); text-align: center; }
.weeks { position: relative; }
.week { display: grid; height: var(--cell); grid-template-columns: repeat(7, var(--cell)); }
.cell, .blank { position: relative; display: block; }

/* The highlight lives under the days: one bar per week plus a solid end at each side of the range. */
.layer { position: absolute; inset: 0; pointer-events: none; }
.bar { position: absolute; height: calc(var(--cell) - 6px); border-radius: var(--radius-pill); background: var(--accent-subtle); }
.thumb { position: absolute; top: 0; left: 0; width: var(--cell); height: var(--cell); }
.thumb::before { content: ""; position: absolute; inset: 3px; border-radius: 50%; background: var(--accent); }

.day {
  position: relative;
  z-index: 1;
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--foreground);
  cursor: pointer;
  font: inherit;
  font-variant-numeric: tabular-nums;
  -webkit-tap-highlight-color: transparent;
  transition: color var(--duration-fast) var(--ease-standard);
}
.day > span { position: relative; display: grid; width: calc(100% - 6px); height: calc(100% - 6px); place-items: center; border-radius: 50%; transition: background-color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard); }
.day:active:not(:disabled) > span { transform: scale(.9); }
.day[data-edge] { color: var(--accent-foreground); font-weight: 500; transition-delay: 40ms; }
.day[data-today]::after { content: ""; position: absolute; bottom: 5px; left: 50%; width: 4px; height: 4px; margin-left: -2px; border-radius: 50%; background: var(--accent); }
.day[data-today][data-edge]::after { background: var(--accent-foreground); }
.day:disabled { color: var(--text-muted); cursor: default; opacity: .5; }
.day:focus-visible:not([data-edge]) > span { background: color-mix(in oklch, var(--foreground) 7%, transparent); }

/* Footer: the formatted range and the two decisions. */
.footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 10px; padding: 10px 2px 0 6px; border-top: 1px solid var(--border-subtle); }
.summary { display: grid; min-width: 0; gap: 1px; }
.summaryValue { display: inline-flex; width: max-content; font-weight: 500; font-variant-numeric: tabular-nums; }
.summaryCount { display: inline-flex; min-height: 1.4em; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.actions { display: flex; flex: none; align-items: center; gap: 6px; }
.ghost, .primary {
  display: inline-flex;
  height: var(--control-height-sm);
  align-items: center;
  justify-content: center;
  padding: 0 14px;
  border: 0;
  border-radius: var(--radius-control);
  cursor: pointer;
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard), opacity var(--duration-fast) var(--ease-standard);
}
.ghost { background: transparent; color: var(--text-secondary); }
.primary { min-width: 4.75rem; background: var(--accent); color: var(--accent-foreground); }
.ghost:active, .primary:active:not(:disabled) { transform: scale(.97); }
.primary:disabled { opacity: .45; cursor: default; }
.ghost:focus-visible { background: var(--surface-muted); color: var(--foreground); }
.preset:focus-visible, .navButton:focus-visible { background: color-mix(in oklch, var(--foreground) 5%, transparent); color: var(--foreground); }

.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

/* Compact: one month under a scrolling row of presets. */
.panel[data-compact] { padding: 8px; }
.panel[data-compact] .body { flex-direction: column; gap: 8px; }
.panel[data-compact] .rail { width: auto; flex-direction: row; gap: 2px; margin: 0 -8px; padding: 0 8px 8px; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--border-subtle); overscroll-behavior-x: contain; scrollbar-width: none; }
.panel[data-compact] .rail::-webkit-scrollbar { display: none; }
.panel[data-compact] .preset { padding: 0 11px; }
.panel[data-compact] .calendars { align-self: center; }
.panel[data-compact] .footer { flex-wrap: wrap; margin-top: 6px; }
.panel[data-compact] .summary { flex: 1 1 8rem; }

@media (hover: hover) and (pointer: fine) {
  .root:not([data-open]):has(> .trigger:hover:not(:disabled)) .surface { background: color-mix(in oklch, var(--foreground) 3%, var(--surface-raised)); }
  .root:not([data-open]):has(> .trigger:hover:not(:disabled)) .surface::after { border-color: var(--border-strong); }
  .preset:hover { color: var(--foreground); }
  .preset:not([aria-pressed="true"]):hover { background: color-mix(in oklch, var(--foreground) 4%, transparent); }
  .navButton:hover:not(:disabled) { background: color-mix(in oklch, var(--foreground) 6.5%, transparent); color: var(--foreground); }
  .day:hover:not(:disabled):not([data-edge]) > span { background: color-mix(in oklch, var(--foreground) 7%, transparent); }
  .ghost:hover { background: var(--surface-muted); color: var(--foreground); }
  .primary:hover:not(:disabled) { background: var(--accent-strong); }
}

@media (prefers-reduced-motion: reduce) {
  .surface, .preset, .navButton, .day, .day > span, .ghost, .primary { transition-duration: 0ms; }
}

@media (prefers-contrast: more) {
  .surface::after { border-color: var(--border-strong); }
}
